export const PEOPLE=[{id:'noa',name:'נועה לוי',initials:'נל',className:'ז׳1',color:'#dceee7'},{id:'omar',name:'עומר חורי',initials:'עח',className:'ז׳1',color:'#e7e7f6'},{id:'maya',name:'מאיה כהן',initials:'מכ',className:'ז׳1',color:'#f7e8cd'},{id:'daniel',name:'דניאל סאלם',initials:'דס',className:'ז׳2',color:'#dcebf5'}];
export const TOPICS={obj_playing:'כללי המשחק',obj_etiquette:'התנהגות במגרש',obj_handicapping:'חישוב ניקוד',obj_havingfun:'שיתוף והנאה',PRIMARYOBJ:'תוצאה כוללת'};
export function uid(){return crypto.randomUUID()}
export function baseState(){return {schema:1,courses:[],assignments:[],attempts:[],role:'teacher',learner:'noa',tickets:[],selectedTicket:null,runs:[],environments:{development:'1.2.0-demo',staging:'1.1.0-demo',production:'1.0.0-demo'},flags:{teacherSummary:{development:true,staging:true,production:false},studentHelp:{development:true,staging:false,production:false}},audit:[],notes:{}}}
export function newAttempt(course,user){const data=course.version==='1.2'?{'cmi.core.student_id':user.id,'cmi.core.student_name':user.name,'cmi.core.lesson_status':'not attempted','cmi.core.lesson_location':'','cmi.core.entry':'ab-initio','cmi.core.total_time':'0000:00:00.00','cmi.core.lesson_mode':'normal','cmi.core.credit':'credit','cmi.suspend_data':''}:{'cmi.learner_id':user.id,'cmi.learner_name':user.name,'cmi.completion_status':'unknown','cmi.success_status':'unknown','cmi.location':'','cmi.entry':'ab-initio','cmi.total_time':'PT0S','cmi.mode':'normal','cmi.credit':'credit','cmi.suspend_data':'','cmi.scaled_passing_score':String(course.mastery/100),'cmi.launch_data':''};(course.objectives||[]).forEach((id,i)=>{data[`cmi.objectives.${i}.id`]=id;data[`cmi.objectives.${i}.completion_status`]='unknown';data[`cmi.objectives.${i}.success_status`]='unknown'});return {id:uid(),courseId:course.id,userId:user.id,startedAt:new Date().toISOString(),updatedAt:new Date().toISOString(),data,events:[],sessions:0,elapsedMs:0,commitCount:0}}
export function numeric(v){return v!==null&&v!==undefined&&v!==''&&Number.isFinite(Number(v))?Number(v):null}
export function interactions(attempt){if(!attempt)return [];const d=attempt.data;const ids=[...new Set(Object.keys(d).map(k=>/^cmi\.interactions\.(\d+)\.id$/.exec(k)?.[1]).filter(x=>x!==undefined))];return ids.map(i=>({index:Number(i),id:d[`cmi.interactions.${i}.id`],description:d[`cmi.interactions.${i}.description`]||d[`cmi.interactions.${i}.id`],response:d[`cmi.interactions.${i}.learner_response`]??d[`cmi.interactions.${i}.student_response`]??'',correct:d[`cmi.interactions.${i}.correct_responses.0.pattern`]??'',result:d[`cmi.interactions.${i}.result`]??'unknown',objective:d[`cmi.interactions.${i}.objectives.0.id`]??'',type:d[`cmi.interactions.${i}.type`]??''})).sort((a,b)=>a.index-b.index)}
export function latestInteractions(attempt){const rows=interactions(attempt),m=new Map();rows.forEach(r=>m.set(r.id,r));return [...m.values()]}
export function summary(attempt,course){if(!attempt)return {status:'not-started',score:null,progress:null,location:null,success:'unknown',questions:0,correct:0,wrong:0};const d=attempt.data;const completion=d['cmi.completion_status']??d['cmi.core.lesson_status']??'unknown';const score=numeric(d['cmi.score.raw']??d['cmi.core.score.raw']);const scaled=numeric(d['cmi.score.scaled']);let success=d['cmi.success_status']??(completion==='passed'||completion==='failed'?completion:'unknown');let derived=false;if(success==='unknown'&&scaled!==null&&course.version==='2004'){success=scaled>=course.mastery/100?'passed':'failed';derived=true}const q=latestInteractions(attempt);return {status:['completed','passed','failed'].includes(completion)?'completed':'active',completion,score,progress:numeric(d['cmi.progress_measure']),location:d['cmi.location']??d['cmi.core.lesson_location']??null,success,derived,questions:q.length,correct:q.filter(x=>x.result==='correct').length,wrong:q.filter(x=>['incorrect','wrong'].includes(x.result)).length}}
export function insights(attempt,course){if(course.kind==='external')return [{kind:'info',title:'התוכן מוצג, ללא דיווח תוצאות',body:'הקישור הציבורי אינו מעביר ציונים או תשובות. אפשר לראות פתיחה וזמן חלון במעטפת בלבד.'}];if(!attempt)return [{kind:'info',title:'הנתונים יופיעו אחרי התחלת הלמידה',body:'נשתמש בדיווחים שהלומדה שולחת, בלי לנחש תשובות או ציונים.'}];const q=latestInteractions(attempt),s=summary(attempt,course);const result=[];if(q.length){const groups={};q.forEach(x=>{const t=x.objective||'unknown';groups[t]??={total:0,wrong:0};groups[t].total++;if(['incorrect','wrong'].includes(x.result))groups[t].wrong++});Object.entries(groups).filter(([,g])=>g.wrong>0).sort((a,b)=>b[1].wrong/b[1].total-a[1].wrong/a[1].total).slice(0,3).forEach(([id,g])=>result.push({kind:'attention',title:`כדאי לחזור על ${TOPICS[id]||'השאלות שסומנו'}`,body:`${g.wrong} מתוך ${g.total} תשובות בנושא סומנו כשגויות בלומדה. מומלץ לעבור עליהן יחד עם התלמיד.`,objective:id}));if(!result.length&&q.every(x=>x.result==='correct'))result.push({kind:'good',title:'כל התשובות המדווחות נכונות',body:`הלומדה דיווחה על ${q.length} תשובות נכונות. אפשר לשקול משימת המשך מתאימה.`})}else result.push({kind:'info',title:course.hasInteractions?'ממתינים לתשובות מהמבחן':'הלומדה מדווחת תוצאה כללית בלבד',body:course.hasInteractions?'מעבר בין מסכי התוכן אינו תשובה לשאלה. פירוט השאלות יופיע לאחר הגשת המבחן.':'אין בחבילה הזו פירוט תשובות לכל שאלה. לא ניתן להסיק ממנה באילו שאלות התלמיד התקשה.'});if(s.status==='completed'&&s.score===null)result.push({kind:'attention',title:'השלמה אינה ציון',body:'הלומדה כבר דיווחה השלמת תוכן, אך עדיין לא התקבל ציון. בדוגמה זו הגעה למסך המבחן מסמנת השלמה גם לפני הגשת תשובות.'});return result}
export function readyTicket(t){return Boolean(t&&t.title.trim()&&t.description.trim()&&t.acceptance.trim()&&t.owner&&t.tester&&t.autoPlan.trim()&&t.manualPlan.trim())}
export function gates(t){if(!t)return [];return [{id:'ticket',label:'טיקט מוגדר ומקושר',ok:readyTicket(t)&&t.status!=='draft'},{id:'review',label:'סקירת CodeRabbit לגרסה הנוכחית',ok:t.review==='approved'&&t.reviewRevision===t.revision},{id:'peer',label:'אישור עמית',ok:t.peer===true&&t.peerRevision===t.revision},{id:'tests',label:'בדיקות אוטומטיות',ok:t.tests==='passed'&&t.testsRevision===t.revision},{id:'coverage',label:'כיסוי 90% בכל מדד ורכיב',ok:t.testsRevision===t.revision&&['frontend','server'].every(k=>['lines','branches','functions'].every(m=>Number.isFinite(t.coverage?.[k]?.[m])&&t.coverage[k][m]>=90))}]}
export function canStage(t){return Boolean(t)&&gates(t).every(g=>g.ok)}
export function canRelease(t){return canStage(t)&&t.stagedRevision===t.revision&&t.manual==='passed'&&t.manualRevision===t.revision&&t.releaseApproval===true}
export function bumpRevision(t){t.revision++;t.review='pending';t.reviewRevision=null;t.peer=false;t.peerRevision=null;t.tests='pending';t.testsRevision=null;t.manual='pending';t.manualRevision=null;t.releaseApproval=false;t.stagedRevision=null;t.coverage=null;t.status='development'}
export function createTicket(n=1){return {id:`OFEK-${100+n}`,title:'',description:'',acceptance:'',owner:'אמיר · פיתוח',tester:'יעל · בדיקות',autoPlan:'',manualPlan:'',status:'draft',revision:1,review:'pending',peer:false,tests:'pending',manual:'pending',coverage:null,releaseApproval:false,fixApplied:false,createdAt:new Date().toISOString()}}
